 const unlocked=atlasUnlocked(current.region,current.contract,current.tier);
 $('siegeAtlasStart').disabled=!unlocked;
 $('siegeAtlasStart').textContent=unlocked?`⚔ START ${rgn.name.toUpperCase()} CONTRACT`:'⌁ CLEAR THE PREVIOUS CONTRACT';
 $('siegeAtlasObjective').textContent=`${REGION_SAGAS[current.region][current.contract]}: ${cn.desc} Survive the selected ${runContract.label({duration:runContract.seconds($('siegeDuration')?.value)})} contract and meet its objective. Tier ${current.tier+1} of ${MASTERIES.length}.${$('siegeDuration')?.value==='endless'?' Endless is free survival: no timed victory, Atlas clear or next-contract unlock.':''}`;
