function startAtlas(){if(portalBusy||state.run?.portalSession){pushToast('Return from the side run before starting an Atlas contract.');return}const {region,contract,tier}=state.atlas.selected;if(!atlasUnlocked(region,contract,tier)){pushToast('Finish the preceding Atlas contract first.','danger');return}const hero=classChoice,diff=$('siegeDifficulty').value;beginRun(hero,diff);const r=state.run,entry=CONTRACT_PATTERNS[contract],realm=REGIONS[region];r.atlas={region,contract,tier,duration:runContract.duration(r),mission:entry.id,chapter:REGION_SAGAS[region][contract]};r.arena=realm.name;r.maxHp+=legacyRank('vigor')*6;r.hp=r.maxHp;r.hazardClock=18;r.omenClock=80;r.peakCombo=0;r.gemsCollected=0;r.evolutions=[];makeTexture(r.arena);cam.x=r.x;cam.y=r.y;dirty=true;renderHUD();updateBuild();pushToast(`${realm.icon} ${realm.name.toUpperCase()} · ${REGION_SAGAS[region][contract]}`);void save()}
function markAtlasClear(r){if(!r.atlas)return;const key=atlasKey(r.atlas.region,r.atlas.contract,r.atlas.tier);const already=Boolean(state.atlas.clears[key]);const record={score:r.score,elapsed:r.elapsed,level:r.level,bosses:r.bossesKilled,hero:r.hero,difficulty:r.difficulty};if(!already){state.atlas.clears[key]=record;state.atlas.essence+=1;const count=atlasSummary().count;pushToast(`✦ FIRST CLEAR ${count} · +1 LEGACY EMBER`);if(r.atlas.contract===7)pushToast(`♛ ${REGIONS[r.atlas.region].relic.toUpperCase()} DISCOVERED`)}const previous=state.atlas.best[key];if(!previous||r.score>previous.score)state.atlas.best[key]=record;dirty=true;}
function buyLegacy(id){const perk=LEGACY_PERKS.find(a=>a.id===id);if(!perk)return;const n=legacyRank(id),cost=n+1;if(n>=perk.max||state.atlas.essence-state.atlas.spent<cost)return;state.atlas.legacy[id]=n+1;state.atlas.spent+=cost;dirty=true;pushToast(`✧ ${perk.name.toUpperCase()} · RANK ${n+1}`);renderAtlas();void save()}
function checkEvolutions(){const r=state.run;if(!r)return;r.evolutions=r.evolutions||[];for(const evo of EVOLUTIONS){if(r.evolutions.includes(evo.id))continue;if(Object.entries(evo.requires).every(([id,n])=>skill(id)>=n)){r.evolutions.push(evo.id);flash();pushToast(`${evo.icon} WEAPON EVOLVED · ${evo.name.toUpperCase()}`);dirty=true}}}
function hasEvolution(id){return Boolean(state.run?.evolutions?.includes(id))}
function omenChoice(i){const r=state.run;if(!r)return;const opts=[
 {id:'blood',name:'Blood for Power',icon:'◈',desc:'+22% all weapon damage; sacrifice 15 maximum health.'},
 {id:'solace',name:'Moonwell Benediction',icon:'☾',desc:'Restore your squad and increase health, but slow movement.'},
 {id:'greed',name:'The Gilded Pact',icon:'✧',desc:'Gain +35% experience, but enemies multiply faster.'},
 {id:'storm',name:'Storm Oath',icon:'ϟ',desc:'Lightning pulses grow stronger, but hostile strikes hurt more.'},
 {id:'dash',name:'Ghoststep Vow',icon:'➳',desc:'Move faster and dodge more often, but start with less health.'},
 {id:'ward',name:'The Iron Root',icon:'⛨',desc:'Take less damage, but your attacks become a little weaker.'}
 ];
 const offer=[opts[(r.omenCount*2+r.atlas.region)%opts.length],opts[(r.omenCount*2+r.atlas.region+2)%opts.length],opts[(r.omenCount*2+r.atlas.region+4)%opts.length]];
 showDialog('omen','ᛟ A FATE IS OFFERED',`CHOICE OF THE ${REGIONS[r.atlas.region].faction.toUpperCase()}`,'Every bargain has a price. Your choice changes the rest of this run.',offer);presentChoices=offer;
}
function applyOmen(c){const r=state.run;if(!r)return;r.omens=r.omens||[];r.omens.push(c.id);switch(c.id){case 'blood':r.maxHp=Math.max(30,r.maxHp-15);r.hp=Math.min(r.hp,r.maxHp);break;case 'solace':r.maxHp+=18;r.hp=Math.min(r.maxHp,r.hp+45);break;case 'greed':r.omenSpawn=(r.omenSpawn||1)*1.25;break;case 'storm':r.omenDamage=(r.omenDamage||1)*1.12;break;case 'dash':r.hp=Math.max(1,r.hp-12);break;case 'ward':r.hp=Math.min(r.maxHp,r.hp+12);break;}pushToast(`ᛟ FATE SEALED · ${c.name.toUpperCase()}`);closeDialog();updateBuild();dirty=true}
function atlasHazards(dt){const r=state.run;if(!r?.atlas)return;const region=regionAt(r);r.debuff=Math.max(0,(r.debuff||0)-dt);
 if(r.elapsed>=r.hazardClock){r.hazardClock=r.elapsed+Math.max(12,21-r.atlas.tier*1.3);r.hazard={x:r.x+rand(-3.2,3.2),y:r.y+rand(-3.2,3.2),windup:1.9,life:6.5,hit:false,kind:region.hazard};}
 const h=r.hazard;if(h){h.windup-=dt;h.life-=dt;if(h.windup<=0&&!h.hit&&hyp(h.x-r.x,h.y-r.y)<2.4){h.hit=true;const amount=Math.round((5+3*r.atlas.tier)*difficulty().damage*(1-.03*legacyRank('warden')));r.hp=Math.max(1,r.hp-amount);r.debuff=region.hazard==='frost'||region.hazard==='tide'||region.hazard==='thorns'?3:0;r.effects.push({x:r.x,y:r.y,text:`-${amount} ${region.icon}`,life:1,color:region.accent});pushToast(`${region.icon} ${region.hazard.toUpperCase()} HAZARD`,'danger')}if(h.life<=0)r.hazard=null}
 if(r.elapsed>=r.omenClock){r.omenClock=r.elapsed+Math.max(105,145-r.atlas.tier*5);r.omenCount++;omenChoice(r.omenCount)}
}
function makeTexture(seed){if(texture&&textureSeed===seed)return;textureSeed=seed;const c=document.createElement('canvas');c.width=320;c.height=320;const cx=c.getContext('2d');cx.fillStyle=(REGIONS.find(r=>r.name===seed)?.ground||'#294038');cx.fillRect(0,0,320,320);for(let i=0;i<600;i++){const x=Math.random()*320,y=Math.random()*320,r=1+Math.random()*4;cx.fillStyle=i%8===0?'#56624a38':'#acc6a20b';cx.fillRect(x,y,r,r)}for(let i=0;i<9;i++){const x=Math.random()*320,y=Math.random()*320;cx.strokeStyle='#b9b7a21f';cx.lineWidth=1.5;cx.beginPath();cx.ellipse(x,y,12+i%4*9,3+i%2,Math.random()*PI,0,TAU);cx.stroke()}texture=c}
function localKey(){return 'mo2-update-arsenal-siege-v1:'+profile}
function pushToast(text,kind='good'){const el=document.createElement('span');el.className='siege-toast '+kind;el.textContent=text;$('siegeToasts').append(el);setTimeout(()=>el.remove(),2400);if($('siegeToasts').children.length>5)$('siegeToasts').firstChild.remove()}
function flash(){if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const f=$('siegeFlash');f.classList.remove('burst');void f.offsetWidth;f.classList.add('burst')}
function showDialog(type,kicker,title,desc,choices,actions=[]){dialogType=type;presentChoices=choices||[];$('siegeDialog').hidden=false;$('siegeDialogKicker').textContent=kicker;$('siegeDialogTitle').textContent=title;$('siegeDialogDesc').textContent=desc||'';$('siegeChoices').innerHTML=presentChoices.map((c,i)=>`<button class="siege-choice" data-choice="${i}"><span class="glyph">${escapeHTML(c.icon||'✧')}</span><span class="rank">${escapeHTML(c.rank||'')}</span><b>${escapeHTML(c.name)}</b><small>${escapeHTML(c.desc)}</small></button>`).join('');$('siegeDialogActions').innerHTML=actions.map((a,i)=>`<button data-dialog-action="${i}">${escapeHTML(a.label)}</button>`).join('');showDialog.actions=actions}
function closeDialog(){siegeUpdateRevision++;dialogType='';$('siegeDialog').hidden=true;screen.focus({preventScroll:true})}
// Recruitment requires travelling to a camp. Levels only grant upgrades.
function modalUpgrade(){upgradeModal()}
function companionCamps(r){
 if(!Array.isArray(r.companionCamps))r.companionCamps=[{id:'watchfire',name:'Watchfire Refuge',x:9,y:5},{id:'waystation',name:'Lost Waystation',x:-12,y:-8}];
 return r.companionCamps;
}
function nearestCamp(){const r=state.run;if(!r)return null;return companionCamps(r).filter(c=>!c.recruited).sort((a,b)=>hyp(a.x-r.x,a.y-r.y)-hyp(b.x-r.x,b.y-r.y))[0]||null}
function recruitAtCamp(){
 const r=state.run,camp=nearestCamp();
 if(!active||!r||r.finished||pausing||dialogType||r.squad.length>=3||!camp||hyp(camp.x-r.x,camp.y-r.y)>2)return false;
 const available=(r.companionRoster||[]).filter(c=>!r.squad.some(m=>m.modId===c.modId));
 const choices=available.map(c=>({...c,id:'warden',icon:'♟',campId:camp.id,desc:`Matched ${c.evidence.join(' + ')}${c.needsReview?' · SUPPORT MOD? Review before choosing':''}. Metadata-inspired ally; original models/voices are not imported.`}));
 // Always keep original allies available so false-positive mod matches never force a choice.
 choices.push(...Object.entries(HEROES).filter(([id])=>!r.squad.some(m=>m.id===id)).map(([id,h])=>({...h,id,campId:camp.id,desc:`Original Siege ally · ${h.intro}`})));
 showDialog('camp','✦ '+camp.name.toUpperCase(),'RECRUIT AN ALLY',available.length?'Choose a mod-inspired companion, then its Siege combat role. Matches are suggestions, not verified NPC assets.':'No unused companion mod matches. Recruit an original Siege ally instead.',choices,[{label:'LEAVE CAMP',perform:closeDialog}]);
 return true;
}
function chooseCampCompanion(c){
 const r=state.run,camp=companionCamps(r).find(p=>p.id===c.campId);
 if(!camp||camp.recruited||hyp(camp.x-r.x,camp.y-r.y)>2||r.squad.length>=3)return;
 if(c.modId){showDialog('camp-role','✦ CHOOSE COMBAT ROLE',c.name,'This is an original Siege combat archetype representing the selected mod, not its extracted abilities.',Object.entries(HEROES).map(([id,h])=>({...c,id,icon:h.icon,name:h.name,companionName:c.name,desc:h.intro})),[{label:'BACK TO CAMP',perform:()=>{closeDialog();recruitAtCamp()}}]);return}
 finishCampRecruit(c);
}
function finishCampRecruit(c){
 const r=state.run,camp=companionCamps(r).find(p=>p.id===c.campId);
 if(!camp||camp.recruited||hyp(camp.x-r.x,camp.y-r.y)>2||r.squad.length>=3||!HEROES[c.id]||(c.modId&&r.squad.some(m=>m.modId===c.modId)))return false;
 r.squad.push({id:c.id,cd:0,...(c.modId?{modId:c.modId,name:c.companionName||c.name,representation:'metadata-inspired'}:{})});camp.recruited=true;dirty=true;
 pushToast(`${(c.companionName||c.name).toUpperCase()} JOINS YOUR SQUAD`);closeDialog();updateBuild();renderHUD();void save();return true;
}
function renderCamp(){const r=state.run,camp=nearestCamp(),button=$('siegeRecruit');if(!r||!button)return;
 button.hidden=r.squad.length>=3||!camp;
 if(!camp)return;const d=hyp(camp.x-r.x,camp.y-r.y);button.disabled=d>2;button.textContent=d<=2?'E · RECRUIT AT '+camp.name.toUpperCase():`✦ ${camp.name} · ${Math.ceil(d)}m · ${camp.x>=r.x?'E':'W'} / ${camp.y>=r.y?'S':'N'}`;
 for(const c of companionCamps(r)){const p=xy(c.x,c.y);if(p.x< -100||p.x>canvasW+100||p.y< -100||p.y>canvasH+100)continue;g.save();g.strokeStyle=c.recruited?'#78918b':'#e8d7ac';g.fillStyle='#071014';g.lineWidth=2;g.beginPath();g.arc(p.x,p.y,2*scale,0,TAU);g.fill();g.stroke();g.font='24px system-ui';g.textAlign='center';g.fillStyle='#f0e3c3';g.fillText(c.recruited?'✓':'♟',p.x,p.y);g.font='12px system-ui';g.fillText(c.name,p.x,p.y+24);g.restore()}
}
function upgradeModal(){const r=state.run;if(!r)return;window.ModhunterAudio?.play('success');const eligible=Object.entries(UPGRADES).filter(([id,v])=>skill(id)<v.max&&!r.banished.includes(id));const shuffled=eligible.map(([id,v])=>({id,...v,weight:Math.random()})).sort((a,b)=>a.weight-b.weight).slice(0,3).map(v=>({...v,rank:`RANK ${skill(v.id)+1} / ${v.max}`}));showDialog('upgrade','✧ THE WEAPONS HEAR YOUR CALL',`LEVEL ${r.level} · CHOOSE AN ASCENSION`,'Evolve your weapons. Build synergies between fire, ice, steel, and magic.',shuffled,[{label:`↻ REROLL (${r.rerolls})`,perform:()=>{if(r.rerolls>0){r.rerolls--;upgradeModal()}}},{label:`⊘ BANISH (${r.banishes})`,perform:()=>{if(r.banishes>0&&presentChoices[0]){r.banishes--;r.banished.push(presentChoices[0].id);upgradeModal()}}}]);}
function applyChoice(i){const r=state.run,c=presentChoices[i];if(!r||!c)return;if(dialogType==='omen'){applyOmen(c);return;}if(dialogType==='camp'){chooseCampCompanion(c);return}if(dialogType==='camp-role'){finishCampRecruit(c);return}if(dialogType==='recruit'){if(!r.squad.some(a=>a.id===c.id)&&r.squad.length<3){r.squad.push({id:c.id,cd:0});pushToast(`${c.name.toUpperCase()} ANSWERS YOUR CALL`)}closeDialog();updateBuild();return}if(dialogType==='upgrade'){r.skills[c.id]=(r.skills[c.id]||0)+1;if(['shield','vitality'].includes(c.id)){r.maxHp+=10;r.hp=Math.min(r.maxHp,r.hp+15)}pushToast(`✦ ${c.name.toUpperCase()} · ${r.skills[c.id]}/${c.max}`);checkEvolutions();flash();closeDialog();updateBuild();return}}
function difficulty(){return DIFFICULTY[state.run?.difficulty||'veteran']||DIFFICULTY.veteran}
function rand(min,max){return min+Math.random()*(max-min)}
function ensureCanvas(){const bounds=screen.getBoundingClientRect(),w=Math.max(280,bounds.width),h=Math.max(280,bounds.height),res=Math.min(2,window.devicePixelRatio||1);if(canvasW!==w||canvasH!==h||dpr!==res){canvasW=w;canvasH=h;dpr=res;screen.width=Math.ceil(w*res);screen.height=Math.ceil(h*res);g.setTransform(res,0,0,res,0,0);}}
function xy(x,y){return {x:(x-cam.x)*scale+canvasW*.5,y:(y-cam.y)*scale+canvasH*.53}}
function targetNearest(x,y,range=25){let best=null,dist=range;for(const e of state.run.entities){const d=hyp(e.x-x,e.y-y);if(d<dist){dist=d;best=e}}return best}
function spawnEnemy(boss=false){
 const r=state.run;if(!r)return;
 const angel=rand(0,TAU),dist=boss?rand(7.5,10.5):rand(14,18),el=r.elapsed,difficultyScale=difficulty();
 const types=el>105?['draugr','wraith','skeever','knight','mage','draugr']:el>30?['draugr','skeever','draugr','wraith']:['draugr','skeever','draugr'];
 // Every live bounty has an entire themed faction, not just one renamed boss.
 // All enemy titles belong to the candidate's exact mod id; only bosses can
 // create bounties, and even those award nothing until a native version upgrade.
 const next=boss?targetMods.find(t=>!r.bossesSeen.includes(t.id)):null;
 const candidate=boss?next:(targetMods.length?targetMods[(r.spawnSerial+Math.floor(r.elapsed/18))%targetMods.length]:null);
 const lore=candidate?withLore(candidate).lore:null;
 const namedChampion=!boss&&!!lore&&r.spawnSerial%9===0;
 const roles={weapon:'knight',armor:'knight',npc:'wraith',creature:'skeever',magic:'mage',quest:'draugr',world:'wraith',animation:'wraith',framework:'draugr'};
 const type=boss?'modboss':lore&&(r.spawnSerial%3!==0)?(roles[lore.kind]||pick(types)):pick(types);
 const hp=(boss?360+el*4:12+el*.35)*difficultyScale.hp*(r.atlas?MASTERIES[r.atlas.tier].factor:1)*(type==='knight'?2:type==='wraith'?.7:1)*(namedChampion?2.1:1);
 const entity={id:++r.spawnSerial,x:r.x+Math.cos(angel)*dist,y:r.y+Math.sin(angel)*dist,type,hp,maxHp:hp,spd:(boss?1.12:type==='skeever'?1.85:type==='wraith'?1.65:1.15)*difficultyScale.spd*(r.atlas?1+r.atlas.tier*.035:1),hitCd:rand(0,.6),windup:0,windupTotal:0,slow:0,burn:0,elite:boss,destTime:0};
 if(candidate){entity.enemyLore=themedFoe(candidate,r.spawnSerial);entity.enemyLore.champion=namedChampion}
 if(boss){
  const fallback={id:null,name:'The Unbound Warden',installedVersion:'',latestVersion:'',nexusId:0};
  const t=next||fallback;
  entity.boss={modId:t.id,name:t.name,encounterName:lore?.bossTitle||t.name,installedVersion:t.installedVersion,latestVersion:t.latestVersion,nexusId:t.nexusId,game:t.game,profileId:profile,archetype:lore?.kind||'practice',source:lore?.provenance||'training'};
  r.activeBossId=entity.id;r.bossesSeen.push(t.id||'practice-'+r.bossesSeen.length);
  pushToast(t.id?`♛ ${entity.boss.encounterName} · ${t.name}`:'♛ THE UNBOUND WARDEN RISES!','boss');flash();
 }
 r.entities.push(entity);return entity;
}
function addProjectile(x,y,angle,speed,damage,kind,ttl=2.3,pierce=0){state.run.projectiles.push({x,y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,damage,kind,life:ttl,pierce,seen:[],size:kind==='meteor'?.43:.17})}
function hitEntity(e,damage,kind='steel'){const r=state.run;if(!e||e.hp<=0)return;window.ModhunterAudio?.play('hit');const critical=Math.random()<.07+.036*skill('crit');let amount=damage*(critical?1.7:1)*(1+.04*legacyRank('warcraft'))*(1+(r.omens?.includes('blood')?.22:0))*(kind==='frost'||kind==='ember'?1+.05*legacyRank('rune'):1);if(hasEvolution('bladefall')&&kind==='steel')amount*=1.16;if(hasEvolution('thunder')&&kind==='frost')amount*=1.15;if(e.elite)amount*=1+.18*skill('focus');e.hp-=amount;if(kind==='frost'&&hasEvolution('glacier'))r.hp=Math.min(r.maxHp,r.hp+Math.min(1.6,amount*.012));if(kind==='frost')e.slow=Math.max(e.slow,1.5+skill('frost')*.2);if(kind==='ember')e.burn=Math.max(e.burn,1.6+skill('ember')*.4);if(skill('blood')&&Math.random()<.13)r.hp=Math.min(r.maxHp,r.hp+amount*.025*skill('blood'));r.effects.push({x:e.x,y:e.y,text:`${critical?'✷ ':''}${Math.round(amount)}`,life:.7,color:kind==='frost'?'#b9e4ff':kind==='ember'?'#ffa988':'#f1d8b0'});if(e.hp<=0)enemyDefeated(e)}
function enemyDefeated(e){const r=state.run;const idx=r.entities.indexOf(e);if(idx<0)return;r.entities.splice(idx,1);if(e.lootRunner&&window.ModhunterTreasureGoblin.finish(r,e,true)){r.rerolls+=2;r.gems.push({x:e.x,y:e.y,value:24,life:70});window.ModhunterAudio?.play('loot');pushToast('◇ TREASURE GOBLIN CAUGHT · +2 rerolls · bonus XP');dirty=true}r.kills++;r.combo++;r.peakCombo=Math.max(r.peakCombo||0,r.combo);r.comboClock=2.8;r.score+=e.elite?100:5+Math.min(25,Math.floor(r.combo/12));r.ultCharge=Math.min(100,r.ultCharge+(e.elite?18:1.2));r.gems.push({x:e.x,y:e.y,value:e.elite?30:e.type==='knight'?8:3,life:70});if(hasEvolution('pyre')&&e.burn>0){for(const foe of [...r.entities])if(hyp(foe.x-e.x,foe.y-e.y)<2.5&&foe!==e)hitEntity(foe,9+skill('ember')*2,'ember')}if(e.enemyLore?.champion&&!e.elite)pushToast(`✷ ${e.enemyLore.name} BANISHED`);if(e.burn&&skill('alchemy')){for(const n of r.entities){if(hyp(n.x-e.x,n.y-e.y)<1.8+.2*skill('alchemy'))n.hp-=6*skill('alchemy')}}if(e.elite){r.bossesKilled++;r.activeBossId='';bossDefeated(e);flash()}}
async function bossDefeated(e){const b=e.boss||{},r=state.run;if(!r)return;let confirmed=false,result=null;if(connected&&b.modId){try{result=await api('POST','siege/boss/defeated',{profileId:profile,modId:b.modId,runId:r.id});confirmed=result.ok!==false}catch(err){console.warn('Siege bounty recording:',err.message)}}if(!active||state.run!==r)return;const m=Boolean(b.modId);showDialog('boss','♛ THE MODHUNTER HAS PREVAILED',m?`VANQUISHED: ${b.encounterName||b.name}`:'THE UNBOUND WARDEN FALLS',m?`The ${b.archetype||"mod"} champion of ${b.name} fell. Boss kill: +100 Hunt Points. ${confirmed?'Quest bound to your MO2 profile.':'Could not bind quest yet.'} Update ${b.name} in MO2 to earn +200 bonus Chronicle points and 10 extra Forge Sigils, on top of the regular update reward.`:'Practice kill: +100 Hunt Points. Connect the MO2 plugin and run an update scan to get bosses named after actual outdated mods.',[],m?[{label:'ϟ AUTO UPDATE · CONFIRM BEFORE INSTALL',perform:()=>{void autoUpdateBoss(b)}},{label:'↗ REVEAL EXACT MOD IN MO2',perform:()=>{void revealBoss(b)}},{label:window.__MODHUNTER_NATIVE_SIEGE_SOURCE__?'↗ OPEN SOURCE · BOTH BROWSERS':'↗ OPEN SOURCE · EXTERNAL',perform:()=>{void openBossSource(b)}},{label:'KEEP SURVIVING',perform:()=>closeDialog()}]:[{label:'KEEP FIGHTING',perform:()=>closeDialog()}]);updateBuild();dirty=true;if(m&&confirmed&&window.__MODHUNTER_NATIVE_SIEGE_SOURCE__)void openBossSource(b)}
let siegeUpdateBusy=false,siegeUpdateRevision=0;
async function autoUpdateBoss(b){
 if(siegeUpdateBusy||!connected||!b.modId||b.profileId!==profile){pushToast('Connect the original MO2 profile; another update check may still be running.');return}
 const run=state.run,owner=profile,attempt=++siegeUpdateRevision;let epoch=null,viewGeneration=0;
 const current=()=>attempt===siegeUpdateRevision&&active&&state.run===run&&profile===owner&&dialogType==='boss-update';
 const back={label:'BACK TO GAME · KEEP DOWNLOAD IN MO2',perform:closeDialog};
 const manual={label:'MANUAL OVERRIDE · CHOOSE FILE ON SOURCE',perform:()=>{siegeUpdateRevision++;showDialog('boss-update-manual','MANUAL FILE CHOICE','AUTO UPDATE DISARMED','Any downloaded archive stays in MO2 Downloads. This Siege flow will not install it. Choose the edition or add-on you want on the verified source page.',[],[{label:'OPEN VERIFIED SOURCE AGAIN',perform:()=>{void openBossSource(b)}},back]);void openBossSource(b)}};
 const show=(title,desc,actions=[])=>showDialog('boss-update','ϟ OPTIONAL AUTO UPDATE',title,desc,[],[...actions,manual,back]);
 show('CHECKING EXACT UPDATE','Matching the installed mod to verified files. Downloads are allowed; installation always waits for your explicit confirmation here.');
 siegeUpdateBusy=true;
 try{
  const snap=await api('GET','snapshot');if(!current())return;
  if(snap.catalog?.profileId!==owner)throw Error('MO2 profile changed. Reopen the original encounter.');epoch=snap.catalog.executionEpoch;
  if(!Number.isSafeInteger(epoch))throw Error('Update the MO2 plugin; this version lacks safe context tracking.');
  const installed=snap.catalog.items?.find(m=>m.id===b.modId);if(!installed)throw Error('The exact mod is no longer installed.');
  const existing=await api('GET','downloads');if(!current())return;
  if(existing.profileId!==owner)throw Error('MO2 profile changed.');
  let pair=Object.entries(existing.downloads||{}).find(([,t])=>t.itemId===b.modId&&t.profileId===owner&&t.installedVersion===installed.installedVersion&&t.targetVersion===installed.update?.latestVersion&&(!t.modId||Number(t.modId)===Number(installed.nexusId))&&['downloading','paused','complete','installing'].includes(t.status));
  let did;
  if(pair){if(pair[1].autoInstallRequested||pair[1].status==='installing')throw Error('This mod already has an installer request from another workflow. Review it in MO2; Siege will not queue another.');did=Number(pair[0]);}
  else {
   const result=await api('POST','quick-update',{profileId:owner,executionEpoch:epoch,itemIds:[b.modId],autoInstall:false});if(!current())return;
   const queued=result.queued?.find(q=>q.itemId===b.modId);if(!queued)throw Error(result.skipped?.[0]?.reason||result.failed?.[0]?.error||'No unique verified file match. Use manual override to choose the correct edition/add-on.');did=Number(queued.downloadId);
  }
  if(!Number.isSafeInteger(did)||did<0)throw Error('MO2 did not return a valid download identity. Check MO2 Downloads before retrying.');
  async function refresh(){
   const view=++viewGeneration,live=()=>current()&&view===viewGeneration;
   if(!live())return;
   try{
    const data=await api('GET','downloads');if(!live())return;const ticket=data.downloads?.[String(did)];
    if(data.profileId!==owner||!ticket||ticket.profileId!==owner||ticket.itemId!==b.modId)throw Error('The profile or exact download changed. Review it in MO2.');
    if(ticket.autoInstallRequested)throw Error('Another workflow enabled automatic installation. Review this ticket in MO2.');
    const name=ticket.fileName||ticket.name||`Archive #${did}`;
    if(ticket.status==='complete'){
     const brief=await api('GET','install-preview?downloadId='+encodeURIComponent(did));if(!live())return;
     if(brief.itemId!==b.modId||Number(brief.downloadId)!==did)throw Error('Install preview does not match this exact mod/download.');
     const description=`Selected: ${brief.archiveName||name}\nFile ID: ${brief.fileId||brief.assetKey||'unknown'} · ${brief.provider||'unknown'}\n${brief.installedVersion||'?'} → ${brief.targetVersion||'?'} · ${brief.profileName||owner} · runtime ${brief.gameRuntime||'unknown'}\n${[...(brief.errors||[]),...(brief.warnings||[])].join('\n')}\n${brief.backup?.includesModFiles?'Complete target mod files and profile backup are supported.':'Profile/load-order backup only; original mod folders are NOT backed up.'} Confirm below to open MO2’s interactive installer, or override the selection. Nothing is installed yet.`;
     let confirming=false;
     const confirm={label:'CONFIRM EXACT FILE · OPEN MO2 INSTALLER',perform:async()=>{
      if(confirming||!live())return;confirming=true;
      try{
       const latest=await api('GET','snapshot');if(!live())return;
       if(latest.catalog?.profileId!==owner||latest.catalog.executionEpoch!==epoch)throw Error('MO2 context changed. Review this update again.');
       const fresh=await api('GET','install-preview?downloadId='+encodeURIComponent(did));if(!live())return;
       const key=x=>x.reviewToken;
       if(!brief.reviewToken||fresh.canInstall!==true||key(fresh)!==key(brief)){await refresh();return}
       showDialog('boss-update','INSTALL REQUEST SENT','OPENING INTERACTIVE INSTALLER',`Confirmed archive: ${brief.archiveName||name}. This request may now reach MO2. Manage cancellation, FOMOD and replacement choices in MO2; leaving this panel cannot recall it.`,[],[{label:'RETURN TO GAME · MANAGE INSTALLER IN MO2',perform:closeDialog}]);
       const result=await api('POST','install',{downloadId:did,confirm:'INSTALL',reviewToken:brief.reviewToken});if(!live())return;
       showDialog('boss-update','INSTALL REQUEST ACCEPTED','CONTINUE IN MO2',result.message||'Complete the interactive installer in MO2. Completion and rewards require native verification.',[],[{label:'RETURN TO GAME · MANAGE INSTALLER IN MO2',perform:closeDialog}]);
      }catch(e){if(live())showDialog('boss-update','INSTALL STATUS','INSTALLATION NOT CONFIRMED',e.message+' Inspect MO2 before retrying if the request may have reached it.',[],[{label:'RETURN TO GAME · CHECK MO2',perform:closeDialog}]);}
     }};
     show(brief.canInstall===true?'REVIEW CHOSEN FILE BEFORE INSTALL':'INSTALL BLOCKED · REVIEW REQUIRED',description,brief.canInstall===true?[confirm]:[]);return;
    }
    show(`DOWNLOAD · ${String(ticket.status||'unknown').toUpperCase()}`,`Selected: ${name}\nFile ID: ${ticket.fileId||ticket.assetId||ticket.assetKey||'unknown'} · Download #${did}\n${ticket.lastError||'MO2 owns this download. No installation will start automatically from this Siege request.'}`,[{label:'REFRESH DOWNLOAD STATUS',perform:()=>{void refresh()}}]);
   }catch(e){if(live())show('UPDATE NEEDS REVIEW',e.message);}
  }
  await refresh();
 }catch(e){if(current())show('AUTO MATCH NEEDS YOUR CHOICE',e.message);}
 finally{siegeUpdateBusy=false;}
}
function bossSourceIntent(b){
 if(!connected||!b.modId||b.profileId!==profile)return '';
 const intent=new URL('modhunter-siege://source');intent.searchParams.set('profileId',profile);intent.searchParams.set('modId',b.modId);return intent.href;
}
function verifiedBossSource(catalog,b){
 if(catalog?.profileId!==profile||b.profileId!==profile)throw Error('MO2 profile changed; reopen the original encounter.');
 const item=catalog.items?.find(m=>m.id===b.modId);if(!item||item.source?.verified!==true)throw Error('The exact mod source is unresolved; review it in the dashboard.');
 const url=new URL(item.source.url),host=url.hostname.replace(/\.$/,'').toLowerCase();if(url.protocol!=='https:'||url.username||url.password||url.port==='0'||!host.includes('.')||/^(?:\d+(?:\.\d+){3}|\[.*\])$/.test(host)||/\.(?:localhost|local|internal|home|lan|test|invalid|example|onion)$/.test(host))throw Error('Source must be a public HTTPS website hostname. IP-address source links require native source review.');
 if(['www.nexusmods.com','nexusmods.com'].includes(url.hostname))url.searchParams.set('tab','files');return url.href;
}
async function openBossSource(b){
 const intent=bossSourceIntent(b);if(!intent){pushToast('Reconnect the original MO2 profile to open this source.','danger');return false}
 if(window.__MODHUNTER_NATIVE_SIEGE_SOURCE__){window.location.assign(intent);return true}
 try{const data=await api('GET','snapshot'),url=verifiedBossSource(data.catalog,b);const opened=window.open(url,'_blank','noopener,noreferrer');
  pushToast(opened?'Source opened externally. Integrated browsing requires the native Modhunter desktop.':'Source launch requested. If no tab appeared, use the verified source link below. Integrated browsing requires native Modhunter.');
  const actions=$('siegeDialogActions');$('siegeVerifiedSource')?.remove();const link=document.createElement('a');link.id='siegeVerifiedSource';link.href=url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='OPEN VERIFIED SOURCE PAGE';actions.append(link);return Boolean(opened);
 }catch(e){pushToast('Source could not be opened: '+e.message,'danger');return false}
}
async function revealBoss(b){if(!b.modId||!connected){pushToast('Connect MO2 to reveal a mod.');return}try{const result=await api('POST','focus',{id:b.modId,profileId:profile});pushToast(result.message||`Focused ${b.name} in MO2`);closeDialog();}catch(e){pushToast('MO2 focus failed: '+e.message,'danger')}}
// A reinforcement reserve is pacing backpressure, not discarded enemies. Existing
// combatants are never culled and delayed spawns do not award kills or rewards.
function spawnClock(dt){const r=state.run;
 const limit=[128,256,512].includes(r.combatLimit)?r.combatLimit:256;
 const rate=(1.7+r.elapsed/28)*difficulty().spawn*(r.atlas?MASTERIES[r.atlas.tier].factor:1)*(r.omenSpawn||1);
 r.spawnBudget+=dt*rate;if(dt>0)dirty=true;
 // Reserve a boss slot and admit a due boss before ordinary reinforcements.
 // A loaded legacy run above its chosen budget drains naturally: no despawn.
 if(r.elapsed>=r.bossClock&&!r.activeBossId&&r.entities.length<limit){spawnEnemy(true);r.bossClock=r.elapsed+85}
 const treasureDue=r.treasureRunner&&!r.treasureRunner.active&&r.treasureRunner.wait<=0;
 const ordinaryLimit=limit-(r.activeBossId?0:1)-(treasureDue?1:0);let spawnCount=0;
 while(r.spawnBudget>=1&&spawnCount<20&&r.entities.length<ordinaryLimit){r.spawnBudget--;spawnEnemy();spawnCount++}
 r.wave=1+Math.floor(r.elapsed/35);
}

function squadPos(index){const r=state.run;const spread=index===0?[0,0]:index===1?[-.75,.85]:[.72,.95];const ca=Math.cos(r.dir),sa=Math.sin(r.dir);return {x:r.x+spread[0]*ca-spread[1]*sa,y:r.y+spread[0]*sa+spread[1]*ca}}
function fireSquad(dt){const r=state.run;for(let i=0;i<r.squad.length;i++){const member=r.squad[i],hero=HEROES[member.id],pos=squadPos(i);member.cd=Math.max(0,member.cd-dt);const enemy=targetNearest(pos.x,pos.y,13);if(member.cd>0||!enemy)continue;const rate=hero.rate*(1+.12*skill('haste')+.13*skill('arrows'));member.cd=1/(rate||1);const angle=Math.atan2(enemy.y-pos.y,enemy.x-pos.x),power=12+5*skill('mastery')+3*skill('blade');if(hero.type==='warrior'||hero.type==='assassin'){const range=hero.type==='assassin'?3.5:2.7;if(hyp(enemy.x-pos.x,enemy.y-pos.y)<range){for(const e of r.entities){const d=hyp(e.x-pos.x,e.y-pos.y),a=Math.atan2(e.y-pos.y,e.x-pos.x);if(d<range&&Math.cos(angle-a)>.5)hitEntity(e,power*(hero.type==='assassin'?1.2:1),'steel')}}else addProjectile(pos.x,pos.y,angle,9,power*.75,'steel',1.6,0);r.effects.push({x:pos.x+Math.cos(angle),y:pos.y+Math.sin(angle),text:'⚔',life:.24,color:hero.color})}
 else if(hero.type==='ranger')addProjectile(pos.x,pos.y,angle,16,power*(1+.17*skill('arrows')),'arrow',2.1,Math.floor(skill('arrows')/2));
 else if(hero.type==='mage')addProjectile(pos.x,pos.y,angle,10,power*(1+.2*skill('lightning')),'frost',2.5,Math.floor(skill('lightning')/2));
 else if(hero.type==='healer'){addProjectile(pos.x,pos.y,angle,10,power*.8,'sun',2.1,1);r.hp=Math.min(r.maxHp,r.hp+1.2)}
 }
}
function autoAbilities(dt){const r=state.run;r.abilityTick+=dt;if(r.abilityTick>=.75){r.abilityTick=0;const candidates=[...r.entities].sort((a,b)=>hyp(a.x-r.x,a.y-r.y)-hyp(b.x-r.x,b.y-r.y));if(skill('lightning')&&candidates[0]){const target=candidates[0];for(const e of candidates.slice(0,1+skill('lightning'))){if(hyp(target.x-e.x,target.y-e.y)<5)hitEntity(e,4+skill('lightning')*5,'frost')}}if(skill('blizzard')){for(const e of candidates){if(hyp(e.x-r.x,e.y-r.y)<3.3+skill('blizzard')*.4)hitEntity(e,4*skill('blizzard'),'frost')}}if(skill('void')){for(const e of candidates)if(hyp(e.x-r.x,e.y-r.y)<3)hitEntity(e,skill('void')*2,'void')}if(skill('raven')&&candidates[0]){const a=Math.atan2(candidates[0].y-r.y,candidates[0].x-r.x);addProjectile(r.x,r.y,a,14,8+skill('raven')*7,'raven',2.4,1)}if(skill('meteor')&&candidates[0]&&Math.random()<.12*skill('meteor')){for(const e of candidates)if(hyp(e.x-candidates[0].x,e.y-candidates[0].y)<2.6)hitEntity(e,18+skill('meteor')*9,'ember');r.effects.push({x:candidates[0].x,y:candidates[0].y,text:'☄',life:.8,color:'#ffbf8b'})}if(skill('regen'))r.hp=Math.min(r.maxHp,r.hp+skill('regen')*.85)}if(skill('orbit')&&r.entities.length){const t=r.elapsed*4;for(const e of r.entities)if(Math.abs(hyp(e.x-r.x,e.y-r.y)-(2+skill('orbit')*.25))<.5&&Math.random()<dt*2)hitEntity(e,6+skill('orbit')*5,'steel')}if(skill('trap')&&Math.random()<dt*.08*skill('trap')){const near=targetNearest(r.x,r.y,4);if(near)hitEntity(near,6+skill('trap')*9,'ember')}
}
function updateEnemies(dt){const r=state.run;for(const e of [...r.entities]){e.slow=Math.max(0,e.slow-dt);if(e.burn>0){e.burn=Math.max(0,e.burn-dt);e.hp-=dt*skill('ember')*3;if(e.hp<=0){enemyDefeated(e);continue}}if(e.lootRunner){if(window.ModhunterTreasureGoblin.move(e,dt,r)){window.ModhunterTreasureGoblin.finish(r,e,false);r.entities=r.entities.filter(n=>n!==e);pushToast('◇ TREASURE GOBLIN ESCAPED · no loot awarded')}continue}const dx=r.x-e.x,dy=r.y-e.y,d=hyp(dx,dy)||.01;e.hitCd=Math.max(0,e.hitCd-dt);if(e.windup>0){e.windup-=dt;if(e.windup<=0){if(d<(e.elite?2:1.1)&&r.dashInv<=0){const amount=(e.elite?21:6)*(difficulty().damage)*(1-.06*skill('shield'))*(r.atlas?1+r.atlas.tier*.16:1)*(r.omens?.includes('storm')?1.1:1)*(r.omens?.includes('ward')?.86:1)*(1-.03*legacyRank('warden'));r.hp=Math.max(0,r.hp-amount);r.effects.push({x:r.x,y:r.y-.5,text:`-${Math.round(amount)}`,life:.7,color:'#ff8c8a'});if(r.hp<=0){endRun(false);return}}e.hitCd=e.elite?1.25:.95}continue}if(d>1.1){const spd=e.spd*(e.slow>0?.47:1)*dt;e.x+=dx/d*spd;e.y+=dy/d*spd}if(d<(e.elite?2:1.05)&&e.hitCd<=0){e.windupTotal=e.elite?.85:.45;e.windup=e.windupTotal;e.hitCd=1}if(d>35&&!e.elite){e.x=r.x+dx/d*22;e.y=r.y+dy/d*22}}
}
function updateProjectiles(dt){const r=state.run;for(const p of r.projectiles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;for(const e of [...r.entities]){if(p.seen.includes(e.id))continue;if(hyp(p.x-e.x,p.y-e.y)<.54+p.size){p.seen.push(e.id);hitEntity(e,p.damage*(p.kind==='ember'?1+.13*skill('ember'):1),p.kind);if(!p.pierce--){p.life=0;break}}}}r.projectiles=r.projectiles.filter(p=>p.life>0)}
function updateGems(dt){const r=state.run;for(const orb of r.gems){orb.life-=dt;const x=r.x-orb.x,y=r.y-orb.y,d=hyp(x,y);if(d<1.1){window.ModhunterAudio?.play('loot');grantRunXP(r,orb.value*(1+.07*legacyRank('soul'))*(r.omens?.includes('greed')?1.35:1));r.gemsCollected=(r.gemsCollected||0)+orb.value;orb.life=0}else if(d<2.4+skill('magnet')*.8){orb.x+=x/d*dt*6;orb.y+=y/d*dt*6}}r.gems=r.gems.filter(o=>o.life>0);if(r.xp>=r.xpNext&&dialogType===''){r.xp-=r.xpNext;r.level++;r.xpNext=Math.round(r.xpNext*1.16+8);r.hp=Math.min(r.maxHp,r.hp+7);modalUpgrade();dirty=true}}
function inputVector(){let x=0,y=0;if(keyState.has('w')||keyState.has('arrowup'))y--;if(keyState.has('s')||keyState.has('arrowdown'))y++;if(keyState.has('a')||keyState.has('arrowleft'))x--;if(keyState.has('d')||keyState.has('arrowright'))x++;x+=touch.x+gamepad.x;y+=touch.y+gamepad.y;const d=hyp(x,y);return d>0?{x:x/d,y:y/d}:{x:0,y:0}}
let portalBusy=false,saveWaiters=[];
function releaseSaveWaiters(){for(const resolve of saveWaiters.splice(0))resolve()}
function samePortalSnapshot(a,b){if(a===b)return true;if(!a||!b||typeof a!=='object'||typeof b!=='object'||Array.isArray(a)!==Array.isArray(b))return false;const keys=Object.keys(a);return keys.length===Object.keys(b).length&&keys.every(k=>Object.prototype.hasOwnProperty.call(b,k)&&samePortalSnapshot(a[k],b[k]))}
async function persistPortalCandidate(candidate){while(saving)await new Promise(resolve=>saveWaiters.push(resolve));saving=true;const owner=profile;try{const val=JSON.parse(JSON.stringify(candidate));if(connected){try{const result=await api('POST','siege/state',{profileId:owner,revision:rev,state:val});rev=result.revision}catch(error){const observed=await api('GET','siege/state');if(observed.profileId!==owner||!samePortalSnapshot(observed.state,val))throw error;rev=observed.revision}}else localStorage.setItem(localKey(),JSON.stringify(val));$('siegeSaveStatus').textContent='SAVED · '+(connected?'MO2 CHRONICLE':'LOCAL PRACTICE')}finally{saving=false;releaseSaveWaiters()}}


function rebindRunEntities(r){if(r?.treasureRunner?.active){const live=r.entities.find(e=>e.id===r.treasureRunner.active.id);if(live)r.treasureRunner.active=live}}
function grantRunXP(r,amount){r.xp+=amount;if(r.portalSession)r.portalSession.earnedXP+=amount}
function openSidePortal(returnRequested=false){const r=state.run;if(!active||state.mode!=='playing'||!r||r.finished||pausing||dialogType||portalBusy)return false;if(r.portalSession){if(!returnRequested)return false;void returnSideRun('extracted');return true}if(!window.ModhunterSidePortal.near(r,r))return false;showDialog('portal','✧ ASTRAL DETOUR','CHOOSE A SIDE RUN','Your complete parent run and its timer freeze. Play a fresh 10, 20 or 30 minute run, then return with earned local XP and unspent extra rerolls. Damage and death here do not harm the parent. No native currency is granted.',[],[...[10,20,30].map(minutes=>({label:`${minutes} MINUTE DETOUR`,perform:()=>{if(state.run===r)void enterSideRun(minutes)}})),{label:'STAY IN THIS RUN',perform:closeDialog}]);return true}
async function enterSideRun(minutes){const parent=state.run;if(portalBusy||!active||state.mode!=='playing'||!parent||parent.finished||parent.portalSession||pausing||![10,20,30].includes(minutes)||!window.ModhunterSidePortal.near(parent,parent)||(dialogType&&dialogType!=='portal'))return false;portalBusy=true;pausing=true;const owner=profile;closeDialog();$('siegeSaveStatus').textContent='PRESERVING PARENT RUN…';try{const snapshot=JSON.parse(JSON.stringify(parent));window.ModhunterSidePortal.consume(snapshot);const packed=await window.ModhunterSidePortal.pack(snapshot);if(state.run!==parent||profile!==owner)return false;const child=newRun(parent.hero,parent.difficulty);child.duration=minutes*60;child.combatLimit=parent.combatLimit;child.companionRoster=JSON.parse(JSON.stringify(parent.companionRoster||[]));companionCamps(child);child.portalSession={v:1,parentId:parent.id,parent:packed,earnedXP:0,initialRerolls:child.rerolls};child.arena='Astral Detour';await persistPortalCandidate({...state,run:child});if(state.run!==parent||profile!==owner)return false;state.run=child;makeTexture(child.arena);keyState.clear();touch.x=touch.y=gamepad.x=gamepad.y=0;cam.x=cam.y=0;dirty=false;pausing=false;lastTick=performance.now();if(active){openGame();updateBuild()}pushToast(`✧ ${minutes} MINUTE SIDE RUN · parent timer frozen`);return true}catch(e){pushToast('Portal could not preserve your parent: '+e.message,'danger');return false}finally{portalBusy=false;pausing=false}}
async function returnSideRun(reason='extracted'){const child=state.run,session=child?.portalSession;if(portalBusy||!session||session.v!==1)return false;portalBusy=true;pausing=true;const owner=profile;closeDialog();$('siegeSaveStatus').textContent='RESTORING PARENT RUN…';try{const parent=await window.ModhunterSidePortal.unpack(session.parent);if(state.run!==child||profile!==owner)return false;if(parent.id!==session.parentId||parent.v!==1||parent.portalSession||!Array.isArray(parent.entities)||!Array.isArray(parent.squad))throw Error('Parent identity is invalid');const earned=Number(session.earnedXP),rerolls=Math.max(0,child.rerolls-session.initialRerolls);if(!Number.isFinite(earned)||earned<0||!Number.isFinite(rerolls))throw Error('Side-run reward record is invalid');parent.xp+=earned;parent.rerolls+=rerolls;rebindRunEntities(parent);await persistPortalCandidate({...state,run:parent,mode:'playing'});if(state.run!==child||profile!==owner)return false;state.run=parent;state.mode='playing';keyState.clear();touch.x=touch.y=gamepad.x=gamepad.y=0;cam.x=parent.x;cam.y=parent.y;makeTexture(parent.arena);dirty=false;pausing=false;lastTick=performance.now();if(active){openGame();updateBuild()}pushToast(`✧ PARENT RESTORED · ${reason} · +${Math.round(earned)} XP · +${rerolls} rerolls`);return true}catch(e){showDialog('portal-error','PARENT SNAPSHOT RETAINED','RETURN NEEDS ATTENTION',e.message,[],[{label:'RETRY RETURN',perform:()=>void returnSideRun(reason)},{label:'KEEP SIDE RUN PAUSED',perform:()=>{}}]);return false}finally{portalBusy=false;pausing=false}}
function updateTreasure(dt){const r=state.run,s=window.ModhunterTreasureGoblin.state(r);if(s.active){const live=r.entities.find(e=>e.id===s.active.id);if(live)s.active=live}const limit=[128,256,512].includes(r.combatLimit)?r.combatLimit:256;const e=window.ModhunterTreasureGoblin.advance(r,dt,r,r.entities.length<limit-(r.activeBossId?0:1));if(e&&!r.entities.some(n=>n.id===e.id)){r.entities.push(e);pushToast('◇ TREASURE GOBLIN · catch it before it escapes!')}dirty=true}
function mineGeode(){const r=state.run;if(!active||state.mode!=='playing'||!r||r.finished||pausing||dialogType)return false;const hit=window.ModhunterGeodeWorm.mine(r,r);if(!hit)return false;if(hit.waiting)return true;dirty=true;if(hit.reward){grantRunXP(r,hit.reward.xp);r.rerolls++;r.geodesMined=(r.geodesMined||0)+1;window.ModhunterAudio?.play('loot');pushToast('◇ GEODE OPENED · +6 XP · +1 reroll');updateGems(0);updateBuild()}else{window.ModhunterAudio?.play('select');pushToast(`◇ GEODE FRACTURED · ${hit.remaining} strikes left`)}void save();return true}
function tick(dt){if(!active||!state.run||state.run.finished||pausing||dialogType)return;const r=state.run;dt=clamp(dt,0,.045);r.elapsed+=dt;window.ModhunterSidePortal.advance(r,dt,r);window.ModhunterGeodeWorm.advance(r,dt,r);r.dashCd=Math.max(0,r.dashCd-dt);r.dashInv=Math.max(0,r.dashInv-dt);r.comboClock=Math.max(0,r.comboClock-dt);if(r.comboClock<=0)r.combo=0;const v=inputVector();if(v.x||v.y){r.dir=Math.atan2(v.y,v.x);const speed=(3.5+.19*skill('movement'))*(1+.02*legacyRank('stride'))*(r.debuff>0?.78:1)*(r.omens?.includes('dash')?1.13:1)*(r.omens?.includes('solace')?.9:1);r.x+=v.x*speed*dt;r.y+=v.y*speed*dt;dirty=true}cam.x+=(r.x-cam.x)*clamp(dt*5,0,1);cam.y+=(r.y-cam.y)*clamp(dt*5,0,1);spawnClock(dt);updateTreasure(dt);atlasHazards(dt);updateEnemies(dt);if(r.hp<=0)return;fireSquad(dt);autoAbilities(dt);updateProjectiles(dt);updateGems(dt);for(const e of r.effects)e.life-=dt;r.effects=r.effects.filter(e=>e.life>0);if(r.portalSession&&runContract.complete(r,r.elapsed)){void returnSideRun('completed');return}if(r.atlas){const progress=contractProgress(r);if(runContract.complete(r,r.elapsed)&&progress.done&&!r.finished)endRun(true)}else if(runContract.complete(r,r.elapsed)&&r.bossesKilled>=1&&!r.finished){endRun(true)}}
function dash(){const r=state.run;if(!r||r.dashCd>0||pausing||dialogType)return;const v=inputVector(),a=(v.x||v.y)?Math.atan2(v.y,v.x):r.dir;r.x+=Math.cos(a)*(2.2+.32*skill('movement'));r.y+=Math.sin(a)*(2.2+.32*skill('movement'));r.dashCd=Math.max(.6,2.2-.17*skill('movement'));r.dashInv=.48;flash();pushToast('↯ WINDSTEP');dirty=true}
function ultimate(){const r=state.run;if(!r||r.ultCharge<100||pausing||dialogType)return;r.ultCharge=0;for(const e of [...r.entities])if(hyp(e.x-r.x,e.y-r.y)<8)hitEntity(e,70+18*skill('mastery'),'ember');flash();pushToast('♛ DRAGON SOUL UNLEASHED!');dirty=true}
function endRun(won){const r=state.run;if(!r||r.finished)return;if(r.portalSession){void returnSideRun(won?'completed':'defeated');return}r.finished=true;r.won=won;window.ModhunterAudio?.play(won?'victory':'warning');pausing=true;state.records.runs++;if(won)state.records.wins++;state.records.bosses+=r.bossesKilled;state.records.totalKills+=r.kills;if(r.atlas){state.atlas.totals.runs++;state.atlas.hours+=r.elapsed/3600;if(won){state.atlas.totals.wins++;markAtlasClear(r)}}state.records.peakScore=Math.max(state.records.peakScore,r.score);state.records.peakWave=Math.max(state.records.peakWave,r.wave);dirty=true;void save();showDialog('end','♛ THE SIEGE REMEMBERS',won?'VICTORY · THE DAWN ENDURES':'THE SIEGE CLAIMS ANOTHER',`Survivor level ${r.level}. ${r.kills} foes defeated. Hunt score ${r.score}. ${r.bossesKilled} mod bosses slain. ${won?(r.atlas?'Your Atlas contract is conquered. The next challenge awaits.':'Your squad has survived its chosen endurance contract.'):'Your next run carries the wisdom you earned.'}`,[],[{label:'RETURN TO THE WAR COUNCIL',perform:()=>{closeDialog();state.run=null;state.mode='menu';openMenu();renderAtlas();dirty=true;void save()}},{label:'RETRY THE SIEGE',perform:()=>{closeDialog();beginRun(classChoice,$('siegeDifficulty').value)}}])}
function fmt(t){return String(Math.floor(t/60)).padStart(2,'0')+':'+String(Math.floor(t%60)).padStart(2,'0')}
function roundRect(x,y,w,h,r=5){g.beginPath();g.roundRect(x,y,w,h,r)}
